resources.string:
Column(verticalArrangement = Arrangement.spacedBy(16.dp)) {
 CaixaDSTextFieldVariant.entries.forEach { variant ->
 CaixaDSTextField(
 value = text,
 onValueChange = { text = it },
 label = variant.name,
 supportingText = hint,
 variant = variant,
 )
 }
}

var text by remember { mutableStateOf("") }
var richText by remember { mutableStateOf(TextFieldValue()) }
CaixaDSBasicTextField(value = text, onValueChange = { text = it })
CaixaDSBasicTextField(value = richText, onValueChange = { richText = it })
